/* ============================================================
   AgendaBot :: Helpers comunes (sin dependencias externas)
   Zona horaria fija: America/Bogota (UTC-5, sin horario de verano)
   ============================================================ */
const TZ_OFFSET_MS = -5 * 60 * 60 * 1000;
function pad(n, l) { return String(n).padStart(l, '0'); }
function ahora() { return new Date(Date.now() + TZ_OFFSET_MS); }
function aFechaISO(d) { return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1, 2) + '-' + pad(d.getUTCDate(), 2); }
function aHoraHM(d) { return pad(d.getUTCHours(), 2) + ':' + pad(d.getUTCMinutes(), 2); }
function hoyISO() { return aFechaISO(ahora()); }
function horaActual() { return aHoraHM(ahora()); }
function timestampCO() { const d = ahora(); return aFechaISO(d) + ' ' + aHoraHM(d) + ':' + pad(d.getUTCSeconds(), 2); }
function sumarDias(f, n) {
  const p = String(f).split('-').map(Number);
  return aFechaISO(new Date(Date.UTC(p[0], p[1] - 1, p[2] + n)));
}
function esFechaValida(s) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(s || ''))) return false;
  const p = String(s).split('-').map(Number);
  if (p[1] < 1 || p[1] > 12) return false;
  const diasMes = new Date(Date.UTC(p[0], p[1], 0)).getUTCDate();
  return p[2] >= 1 && p[2] <= diasMes && p[0] >= 2000 && p[0] <= 2100;
}
function esHoraValida(s) { return /^([01]\d|2[0-3]):[0-5]\d$/.test(String(s || '')); }
function esPasado(f, h) {
  const hoy = hoyISO();
  if (f < hoy) return true;
  if (f === hoy && h && h <= horaActual()) return true;
  return false;
}
function vacio(s) { return String(s == null ? '' : s).trim().length === 0; }
function limpiar(s) { return String(s == null ? '' : s).trim().replace(/\s+/g, ' ').slice(0, 200); }
function filasReales(items, clave) {
  return items.map(function (i) { return i.json; })
              .filter(function (r) { return r && r[clave] != null && String(r[clave]).trim() !== ''; });
}
function siguienteId(filas, campo, prefijo) {
  let max = 0;
  for (const r of filas) {
    const m = String(r[campo] || '').match(/(\d+)\s*$/);
    if (m) { const n = parseInt(m[1], 10); if (n > max) max = n; }
  }
  return prefijo + '-' + pad(max + 1, 3);
}
function leerDatos(t) { try { const o = JSON.parse(t || '{}'); return (o && typeof o === 'object') ? o : {}; } catch (e) { return {}; } }
function esVerdadero(v) {
  const s = String(v == null ? '' : v).trim().toUpperCase();
  return s === 'TRUE' || s === 'VERDADERO' || s === 'SI' || s === 'SÍ' || s === '1' || s === 'X' || s === 'YES';
}
const PIE = '\n————————\n9 Volver   ·   /menu Menú principal   ·   /cancelar Cancelar';
function opcionInvalida(extra) {
  return '⚠️ No entendí esa opción.\n' + (extra || 'Escribe únicamente el número de una de las opciones mostradas.');
}
function salida(mensaje, pantalla, paso, datos, resultado, accion, fila) {
  return [{ json: {
    mensaje: String(mensaje).slice(0, 3900),
    pantalla_nueva: pantalla,
    paso_nuevo: String(paso),
    datos_parciales: JSON.stringify(datos || {}),
    resultado: resultado || 'OK',
    accion: accion || 'NINGUNA',
    fila: fila || {}
  }}];
}

/* =====================================================================
   MODULO RECORDATORIOS  (solo consulta, no escribe en Google Sheets)
   Pantalla: RECORDATORIOS
   Fuentes: CITAS (rama 1 del Merge) + TAREAS (rama 2 del Merge)
   ===================================================================== */
const ctx = $('▶️ Entrada Recordatorios').first().json;
const citas = filasReales($('📄 CITAS - Leer').all(), 'id_cita');
const tareas = filasReales($('📄 TAREAS - Leer').all(), 'id_tarea');

const texto = String(ctx.texto || '').trim();
const usuario = String(ctx.telegram_user);
const HOY = hoyISO();
const AHORA = horaActual();
const ACTIVAS = ['PENDIENTE', 'REPROGRAMADA'];
const ABIERTAS = ['PENDIENTE', 'EN PROGRESO'];

const MENU =
  '🔔 RECORDATORIOS\n' +
  'Aquí ves lo que se viene y lo que está por vencer.\n\n' +
  '1  Próximas 24 horas\n' +
  '2  Próximos 7 días\n' +
  '3  Agenda de hoy\n' +
  '4  Tareas vencidas y por vencer\n' +
  '9  Volver al menú principal\n\n' +
  '💡 Recomendado: 1 Próximas 24 horas\n' +
  'Tip: escribe únicamente el número.';

/* Entrada directa desde el menu principal: se muestra el menu del modulo
   sin consumir el numero que el usuario uso para entrar. */
if (ctx.entrada_modulo === true || String(ctx.entrada_modulo) === 'true')
  return salida(MENU, 'RECORDATORIOS', '0', {}, 'MENU_RECORDATORIOS');

function misCitas() {
  return citas.filter(function (c) {
    return String(c.creado_por || '').trim() === usuario &&
           ACTIVAS.indexOf(String(c.estado || '').toUpperCase()) !== -1;
  }).sort(function (a, b) {
    return (String(a.fecha) + String(a.hora)).localeCompare(String(b.fecha) + String(b.hora));
  });
}
function misTareas() {
  return tareas.filter(function (t) {
    return String(t.creado_por || '').trim() === usuario &&
           ABIERTAS.indexOf(String(t.estado || '').toUpperCase()) !== -1;
  });
}
function pinta(cs) {
  return cs.map(function (c) {
    return '• ' + c.fecha + '  ' + c.hora + '   ' + c.nombre +
           '\n    ' + c.motivo + '  ·  ' + c.canal + '  ·  ' + c.id_cita;
  }).join('\n');
}

if (texto === '9')
  return salida('👌 Volvamos al menú principal.\n\nEscribe /menu para verlo.',
                'MENU', '0', {}, 'VOLVER');

if (texto === '1') {
  const limite = sumarDias(HOY, 1);
  const cs = misCitas().filter(function (c) {
    const f = String(c.fecha), h = String(c.hora);
    if (f === HOY) return h >= AHORA;
    if (f === limite) return h <= AHORA;
    return false;
  });
  if (cs.length === 0)
    return salida('😌 No tienes nada agendado en las próximas 24 horas.\n\n' + MENU,
                  'RECORDATORIOS', '0', {}, 'SIN_EVENTOS');
  return salida('⏰ PRÓXIMAS 24 HORAS (' + cs.length + ')\n\n' + pinta(cs) + '\n\n' + MENU,
                'RECORDATORIOS', '0', {}, 'CONSULTA_24H');
}

if (texto === '2') {
  const limite = sumarDias(HOY, 7);
  const cs = misCitas().filter(function (c) {
    return String(c.fecha) >= HOY && String(c.fecha) <= limite;
  });
  if (cs.length === 0)
    return salida('😌 No tienes citas en los próximos 7 días.\n\n' + MENU,
                  'RECORDATORIOS', '0', {}, 'SIN_EVENTOS');
  return salida('📆 PRÓXIMOS 7 DÍAS (' + HOY + ' → ' + limite + ')\n' +
                cs.length + ' cita(s)\n\n' + pinta(cs.slice(0, 20)) + '\n\n' + MENU,
                'RECORDATORIOS', '0', {}, 'CONSULTA_7D');
}

if (texto === '3') {
  const cs = misCitas().filter(function (c) { return String(c.fecha) === HOY; });
  const pend = cs.filter(function (c) { return String(c.hora) >= AHORA; });
  if (cs.length === 0)
    return salida('☀️ Hoy (' + HOY + ') no tienes citas agendadas.\n' +
                  'Aprovecha para adelantar tus tareas.\n\n' + MENU,
                  'RECORDATORIOS', '0', {}, 'SIN_EVENTOS');
  return salida('☀️ AGENDA DE HOY  ' + HOY + '\n' +
                cs.length + ' cita(s) · ' + pend.length + ' aún por delante (son las ' + AHORA + ')\n\n' +
                pinta(cs) + '\n\n' + MENU, 'RECORDATORIOS', '0', {}, 'CONSULTA_HOY');
}

if (texto === '4') {
  const ts = misTareas();
  const vencidas = ts.filter(function (t) { return t.fecha_objetivo && String(t.fecha_objetivo) < HOY; });
  const hoyT = ts.filter(function (t) { return String(t.fecha_objetivo) === HOY; });
  const semana = ts.filter(function (t) {
    return t.fecha_objetivo && String(t.fecha_objetivo) > HOY && String(t.fecha_objetivo) <= sumarDias(HOY, 7);
  });
  const sinFecha = ts.filter(function (t) { return !t.fecha_objetivo; });
  function lst(x) {
    return x.length === 0 ? '   (ninguna)'
      : x.map(function (t) { return '   • ' + t.titulo + '  [' + t.prioridad + ']' +
              (t.fecha_objetivo ? '  📅 ' + t.fecha_objetivo : ''); }).join('\n');
  }
  return salida('📌 ESTADO DE TUS TAREAS   (hoy: ' + HOY + ')\n\n' +
                '🔴 VENCIDAS (' + vencidas.length + ')\n' + lst(vencidas) + '\n\n' +
                '🟠 PARA HOY (' + hoyT.length + ')\n' + lst(hoyT) + '\n\n' +
                '🟡 ESTA SEMANA (' + semana.length + ')\n' + lst(semana) + '\n\n' +
                '⚪ SIN FECHA (' + sinFecha.length + ')\n' + lst(sinFecha) + '\n\n' + MENU,
                'RECORDATORIOS', '0', {}, 'CONSULTA_TAREAS');
}

return salida(opcionInvalida('En Recordatorios espero 1, 2, 3, 4 o 9.') + '\n\n' + MENU,
              'RECORDATORIOS', '0', {}, texto === '' ? 'VACIO' : 'OPCION_INVALIDA');

const r = $('🧠 Lógica de Recordatorios').first().json;
return [{ json: {
  mensaje: r.mensaje, pantalla_nueva: r.pantalla_nueva, paso_nuevo: r.paso_nuevo,
  datos_parciales: r.datos_parciales, resultado: r.resultado
}}];
